css:
/* O wrapper precisa de position: relative — é ele que ancora o indicador. */
.demo-hero { position: relative; min-height: 300px; display: flex; align-items: center; padding: 0 60px; }
.demo-hero-inner { max-width: 1360px; margin: 0 auto; width: 100%; }
.demo-titulo { font-weight: 700; font-size: clamp(22px, 3vw, 34px); letter-spacing: -0.03em; }

.hero-scroll {
  position: absolute; left: 0; right: 0; bottom: clamp(20px, 3vh, 40px);
  padding: 0 60px;
  pointer-events: none;
}
.hero-scroll-inner {
  max-width: 1360px; margin: 0 auto;
  display: flex; flex-direction: column; align-items: flex-start; gap: 12px;
}
.hero-scroll-label {
  font-size: 10px; color: var(--text-dimmer);
  letter-spacing: 0.25em; text-transform: uppercase;
}
.hero-scroll-line {
  position: relative; width: 1px; height: clamp(28px, 5vh, 48px);
  background: var(--border-alt); overflow: hidden;
}
/* Um segmento do accent desce pela linha, em looping. */
.hero-scroll-line::after {
  content: ''; position: absolute; left: 0; top: 0;
  width: 1px; height: 40%;
  background: var(--accent);
  animation: hero-scroll-run 2s cubic-bezier(0.65, 0, 0.35, 1) infinite;
}
@keyframes hero-scroll-run {
  0%   { transform: translateY(-100%); opacity: 0; }
  30%  { opacity: 1; }
  70%  { opacity: 1; }
  100% { transform: translateY(250%); opacity: 0; }
}
@media (prefers-reduced-motion: reduce) {
  .hero-scroll-line::after { animation: none; transform: none; opacity: 1; }
}

@media (max-width: 700px) {
  .hero-scroll { display: none; }
}
